# ============================================================
# JSON HELPERS
# ============================================================

def load_json(path, default):
    try:
        if not path.exists():
            return default

        with open(path, "r", encoding="utf-8") as file:
            return json.load(file)

    except Exception:
        return default


def save_json(path, data):
    try:
        path.parent.mkdir(parents=True, exist_ok=True)

        with open(path, "w", encoding="utf-8") as file:
            json.dump(
                data,
                file,
                indent=4
            )

        return True

    except Exception:
        return False


def ensure_list(data):
    if isinstance(data, list):
        return data

    if isinstance(data, dict):
        return [data]

    return []


def get_status(case):
    return case.get(
        "status",
        "UNKNOWN"
    )


def get_risk(case):
    return case.get(
        "risk_level",
        case.get(
            "risk",
            "UNKNOWN"
        )
    )


def get_score(case):
    value = case.get(
        "risk_score",
        0
    )

    try:
        return int(value)
    except Exception:
        return 0


